package com.yeyamo_mobile.api.referral_service.domain;import static org.junit.jupiter.api.Assertions.*;import java.time.*;import org.junit.jupiter.api.Test;import com.yeyamo_mobile.api.referral_service.infrastructure.persistence.ReferralCodeEntity;
class ReferralCodeEntityTest{@Test void consumesUntilLimit(){var code=ReferralCodeEntity.create("abc","owner",2,null);code.consume();assertEquals(1,code.getUsageCount());assertTrue(code.usableAt(Instant.now()));code.consume();assertFalse(code.usableAt(Instant.now()));}@Test void rejectsConsumptionAfterLimit(){var code=ReferralCodeEntity.create("abc","owner",1,null);code.consume();assertThrows(ReferralException.class,code::consume);}@Test void disablesCode(){var code=ReferralCodeEntity.create("abc","owner",1,null);code.disable();assertEquals(ReferralCodeStatus.DISABLED,code.getStatus());assertFalse(code.usableAt(Instant.now()));}@Test void normalizesCode(){assertEquals("ABC",ReferralCodeEntity.create("abc","owner",1,null).getCode());}}
